//go:build (linux || darwin) && arm64 && !tinygo

package runtime

import (
	"encoding/binary"
	"fmt"
	"os"
	goruntime "runtime"
)

var integerSharedHostPrototypeEnabled = os.Getenv("WAGO_INTEGER_SHARED_PROTOTYPE") == "1"

// Diagnostic only: the invoking test pins an integer-only artifact hash.
func (e *Engine) tryIntegerSharedHostPrototype(code uintptr, args []byte, linMem uintptr, trap, results, ctrl []byte, slots uint32, fixed FixedScalarHostCall) (bool, error) {
	if !integerSharedHostPrototypeEnabled {
		return false, nil
	}
	old := binary.LittleEndian.Uint64(ctrl[hcTrampoline:])
	bridge := uint64(inlineHostIntegerBridgeAddr())
	binary.LittleEndian.PutUint64(ctrl[hcTrampoline:], bridge)
	defer func() {
		binary.LittleEndian.PutUint64(ctrl[hcTrampoline:], old)
		goruntime.KeepAlive(e)
		goruntime.KeepAlive(args)
		goruntime.KeepAlive(trap)
		goruntime.KeepAlive(results)
		goruntime.KeepAlive(ctrl)
	}()
	if outcome := inlineHostIntegerScalarPrototypeEnter(fixed, code, slicePtr(args), linMem, slicePtr(trap), slicePtr(results), e.stackTop, slicePtr(ctrl), slots); outcome == 1 {
		return true, fmt.Errorf("jit: inline host escaped admitted import")
	}
	if tc := loadTrap(trap); tc != 0 {
		return true, trapErrorFromBuffer(TrapCode(tc), trap)
	}
	return true, nil
}

//go:noescape
func inlineHostIntegerScalarPrototypeEnter(fn FixedScalarHostCall, code, args, linMem, trap, results, stack, ctrl uintptr, slots uint32) uint64

