//go:build (linux || darwin) && (amd64 || arm64) && !tinygo

package wago

import (
	"context"
	"crypto/sha256"
	"fmt"
	"github.com/wago-org/wago/src/core/compiler/wasm"
	"os"
	"testing"
)

//go:noinline
func fixedSharedOpaqueDiagnostic(v int32) int32 { return v }
func BenchmarkFixedSharedOpaqueDiagnostic(b *testing.B) {
	data, err := os.ReadFile(os.Getenv("WAGO_FIXED_SHARED_DIAGNOSTIC"))
	if err != nil {
		b.Fatal(err)
	}
	if got := fmt.Sprintf("%x", sha256.Sum256(data)); got != "c9310c605dd85f4832d474a2c4e14aee30e2864c048b4c40327bbcfe8321eb53" {
		b.Fatalf("unverified integer fixture %s", got)
	}
	m, err := wasm.DecodeModule(data)
	if err != nil {
		b.Fatal(err)
	}
	for i, fn := range m.Code {
		b.Logf("function%d bytes=%d", i, len(fn.BodyBytes))
	}
	cfg := NewRuntimeConfig().WithMaxModuleBytes(uint64(len(data))).WithFeature(CoreFeatureThreads, true).WithBoundsChecks(BoundsChecksExplicit)
	rt := NewRuntime(WithRuntimeConfig(cfg))
	defer rt.Close()
	host, err := rt.NewHostFuncRef(func(v int32) int32 { return fixedSharedOpaqueDiagnostic(v) }, FuncSig{Params: []ValType{ValI32}, Results: []ValType{ValI32}})
	if err != nil {
		b.Fatal(err)
	}
	defer host.Close()
	mod, err := rt.Compile(data)
	if err != nil {
		b.Fatal(err)
	}
	defer mod.Close()
	in, err := rt.Instantiate(context.Background(), mod, WithImports(NewImports().Function("wasmbench", "identity", host)))
	if err != nil {
		b.Fatal(err)
	}
	defer in.Close()
	fn, err := in.WasmFunc("performance")
	if err != nil {
		b.Fatal(err)
	}
	b.Logf("portalBounded=%t certificate=%t bounded=%t directTyped=%t expandedTyped=%t gate=%t shared=%t privateThreaded=%t", in.boundedFixedSharedHostPortal(), in.c.fixedSharedHostSegments, in.boundedHostSegments(), in.hasSingleDirectTypedScalarHost(), in.hasSingleExpandedTypedScalarHost(), in.syncHosts[0].gate != nil, in.threadedMemoryZero, in.usesPrivateThreadedExecution())
	got, err := fn.Invoke(4096)
	if err != nil || len(got) != 1 || got[0] != 536739840 {
		b.Fatalf("oracle %v %v", got, err)
	}
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		got, err = fn.Invoke(4096)
		if err != nil || len(got) != 1 || got[0] != 536739840 {
			b.Fatalf("oracle %v %v", got, err)
		}
	}
}

